files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --bar: #533483;
  --bar-highlight: #e94560;
  --focus: #f5c518;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 720px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary);
  text-align: center;
}

.subtitle {
  text-align: center;
  color: var(--text-muted);
  font-size: 1rem;
}

fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

legend {
  font-weight: 600;
  margin-bottom: 12px;
  font-size: 0.95rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.inputs {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
}

.input-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.input-group label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
}

.input-group input {
  width: 100%;
  min-width: 0;
  padding: 8px 4px;
  font-size: 1rem;
  font-family: var(--font);
  text-align: center;
  border: 2px solid var(--secondary);
  border-radius: 8px;
  background: var(--secondary);
  color: var(--text);
  transition: border-color 0.2s, background 0.2s;
}

.input-group input:hover {
  border-color: var(--primary);
}

.input-group input:focus {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--primary);
}

.input-group input:active {
  background: #0a2540;
}

.chart-section {
  width: 100%;
}

.chart {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
  height: 200px;
  padding-top: 8px;
  border-bottom: 2px solid var(--secondary);
}

.bar-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
  gap: 4px;
}

.bar {
  width: 100%;
  max-width: 48px;
  background: var(--bar);
  border-radius: 6px 6px 0 0;
  transition: height 0.3s ease, background 0.3s;
  position: relative;
  min-height: 2px;
}

.bar.highlight {
  background: var(--bar-highlight);
  box-shadow: 0 0 12px var(--bar-highlight);
}

.bar-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 600;
  text-transform: uppercase;
}

.average {
  text-align: center;
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--text);
  padding: 12px;
  background: var(--secondary);
  border-radius: 8px;
}

.average span {
  color: var(--primary);
  font-size: 1.5rem;
}

@media (max-width: 480px) {
  .app { padding: 16px; }
  h1 { font-size: 1.4rem; }
  .inputs { grid-template-columns: repeat(4, 1fr); }
  .chart { height: 160px; }
  .bar-label { font-size: 0.65rem; }
}

@media (max-width: 360px) {
  .inputs { grid-template-columns: repeat(3, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  .bar, .input-group input { transition: none; }
}

(function () {
  'use strict';

  const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const MAX_HOURS = 12;
  const STORAGE_KEY = 'sleep-tracker-data';

  const inputsContainer = document.getElementById('inputs-container');
  const chartEl = document.getElementById('chart');
  const averageValueEl = document.getElementById('average-value');

  let values = loadValues();

  function loadValues() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed) && parsed.length === 7) {
          return parsed.map(function (v) {
            const n = Number(v);
            return isFinite(n) ? Math.min(MAX_HOURS, Math.max(0, n)) : 0;
          });
        }
      }
    } catch (e) { /* ignore */ }
    return [0, 0, 0, 0, 0, 0, 0];
  }

  function saveValues() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(values));
    } catch (e) { /* ignore */ }
  }

  function buildInputs() {
    DAYS.forEach(function (day, i) {
      const group = document.createElement('div');
      group.className = 'input-group';

      const label = document.createElement('label');
      label.setAttribute('for', 'input-' + i);
      label.textContent = day;

      const input = document.createElement('input');
      input.type = 'number';
      input.id = 'input-' + i;
      input.min = '0';
      input.max = String(MAX_HOURS);
      input.step = '0.5';
      input.value = String(values[i]);
      input.setAttribute('aria-label', day + ' hours slept');

      input.addEventListener('input', function () {
        let v = parseFloat(input.value);
        if (isNaN(v)) v = 0;
        v = Math.min(MAX_HOURS, Math.max(0, v));
        values[i] = v;
        saveValues();
        render();
      });

      input.addEventListener('change', function () {
        let v = parseFloat(input.value);
        if (isNaN(v)) v = 0;
        v = Math.min(MAX_HOURS, Math.max(0, v));
        values[i] = v;
        input.value = String(v);
        saveValues();
        render();
      });

      group.appendChild(label);
      group.appendChild(input);
      inputsContainer.appendChild(group);
    });
  }

  function render() {
    const maxVal = Math.max.apply(null, values);
    const hasData = values.some(function (v) { return v > 0; });

    chartEl.innerHTML = '';
    values.forEach(function (v, i) {
      const wrapper = document.createElement('div');
      wrapper.className = 'bar-wrapper';

      const bar = document.createElement('div');
      bar.className = 'bar';
      const heightPct = hasData ? (v / MAX_HOURS) * 100 : 0;
      bar.style.height = Math.max(heightPct, v > 0 ? 2 : 0) + '%';

      if (v > 0 && v === maxVal) {
        bar.classList.add('highlight');
        bar.setAttribute('aria-label', DAYS[i] + ': ' + v + ' hours (longest night)');
      } else {
        bar.setAttribute('aria-label', DAYS[i] + ': ' + v + ' hours');
      }

      const label = document.createElement('span');
      label.className = 'bar-label';
      label.textContent = DAYS[i];

      wrapper.appendChild(bar);
      wrapper.appendChild(label);
      chartEl.appendChild(wrapper);
    });

    const sum = values.reduce(function (a, b) { return a + b; }, 0);
    const avg = sum / 7;
    averageValueEl.textContent = avg.toFixed(1);

    chartEl.setAttribute('aria-label', 'Bar chart: ' + values.map(function (v, i) {
      return DAYS[i] + ' ' + v + 'h';
    }).join(', ') + '. Weekly average ' + avg.toFixed(1) + ' hours.');
  }

  buildInputs();
  render();
})();
